const data=window.portfolioContent,page=document.body.dataset.page||'home',app=document.getElementById('app');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nav=[['projects','Projects'],['about','About'],['resume','Resume'],['connect','Connect']];
const header=`<header class="site-header"><a class="wordmark" href="index.html" aria-label="返回首页">${esc(data.name)}<span>.</span></a><nav aria-label="主导航">${nav.map(([key,label])=>`<a href="${key}.html" ${page===key?'aria-current="page"':''}>${label}${key==='connect'?' <span aria-hidden="true">↗</span>':''}</a>`).join('')}</nav></header>`;
const footer=`<footer class="site-footer wrap"><span>© ${new Date().getFullYear()} ${esc(data.name)}</span><a href="index.html">返回首页 ↑</a></footer>`;
let main='';
if(page==='home')main=`<main class="home wrap"><div class="eyebrow"><span class="status-dot"></span>${esc(data.home.eyebrow)}</div><h1>${esc(data.home.title)}</h1><div class="home-bottom"><p>${esc(data.home.intro)}</p><a class="text-link" href="projects.html">${esc(data.home.cta)} <span aria-hidden="true">↗</span></a></div></main>`;
else if(page==='projects')main=`<main class="wrap inner-page"><div class="page-head"><span class="kicker">01 / 作品</span><h1>${esc(data.projects.title)}</h1><p>${esc(data.projects.intro)}</p></div><div class="project-grid">${data.projects.items.map((item,i)=>`<article class="project-card"><div class="project-cover cover-${i+1}">${item.image?`<img src="${esc(item.image)}" alt="${esc(item.title)} 项目封面">`:`<div class="cover-graphic" aria-hidden="true"><span>${String(i+1).padStart(2,'0')}</span><i></i><b></b></div>`}<span class="cover-index">${String(i+1).padStart(2,'0')} / 06</span></div><div class="card-meta"><span>${esc(item.type)}</span><span>${String(i+1).padStart(2,'0')}</span></div><h2>${esc(item.title)}</h2><p>${esc(item.description)}</p></article>`).join('')}</div></main>`;
else{const s=data[page],num={about:'02',resume:'03',connect:'04'}[page],label={about:'关于',resume:'简历',connect:'联系'}[page];main=`<main class="wrap inner-page text-page"><div class="page-head"><span class="kicker">${num} / ${label}</span><h1>${esc(s.title)}</h1></div><div class="text-content"><h2>${esc(s.lead)}</h2><p>${esc(s.body)}</p><div class="note">${esc(s.note)}</div></div></main>`}
app.innerHTML=header+main+footer;
